ALTER TABLE source_watches ADD CONSTRAINT source_watches_owner_key UNIQUE(id,user_id);
ALTER TABLE source_change_events ADD CONSTRAINT source_change_owner_key UNIQUE(id,user_id);
CREATE TABLE pick_reason_versions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,pick_id text NOT NULL,pick_version integer NOT NULL,revision integer NOT NULL CHECK(revision>0),payload jsonb NOT NULL CHECK(octet_length(payload::text)<=65536),confirmed_at timestamptz NOT NULL DEFAULT clock_timestamp(),mode text NOT NULL DEFAULT 'live' CHECK(mode IN ('live','acceptance_test','replay','synthetic')),UNIQUE(user_id,pick_id,pick_version,revision),UNIQUE(id,user_id),FOREIGN KEY(pick_id,user_id,pick_version) REFERENCES pick_versions(pick_id,user_id,version));
CREATE TABLE pick_watch_bindings(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,reason_id text NOT NULL,watch_id text NOT NULL,condition_index integer NOT NULL CHECK(condition_index BETWEEN 0 AND 3),state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','paused')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(reason_id,watch_id,condition_index),FOREIGN KEY(reason_id,user_id) REFERENCES pick_reason_versions(id,user_id),FOREIGN KEY(watch_id,user_id) REFERENCES source_watches(id,user_id));
CREATE TABLE source_lineage_edges(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,from_evidence_id text NOT NULL,to_evidence_id text NOT NULL,payload jsonb NOT NULL CHECK(octet_length(payload::text)<=8192),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(from_evidence_id<>to_evidence_id));
CREATE TABLE pick_impact_assessments(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,change_id text NOT NULL,reason_id text NOT NULL,reason_revision integer NOT NULL,pick_id text NOT NULL,pick_version integer NOT NULL,rules_version text NOT NULL,state text NOT NULL CHECK(state IN ('needs_review','waiting_confirmation','check_unavailable','still_watching')),payload jsonb NOT NULL CHECK(octet_length(payload::text)<=65536),checked_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(user_id,change_id,reason_id,reason_revision,rules_version),UNIQUE(id,user_id),FOREIGN KEY(change_id,user_id) REFERENCES source_change_events(id,user_id),FOREIGN KEY(reason_id,user_id) REFERENCES pick_reason_versions(id,user_id),FOREIGN KEY(pick_id,user_id,pick_version) REFERENCES pick_versions(pick_id,user_id,version));
CREATE TABLE pick_review_actions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,assessment_id text NOT NULL,request_id text NOT NULL,action text NOT NULL CHECK(action IN ('keep','update','stop_watching')),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(user_id,assessment_id,request_id),FOREIGN KEY(assessment_id,user_id) REFERENCES pick_impact_assessments(id,user_id));
CREATE TABLE decision_recap_versions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,pick_id text NOT NULL,revision integer NOT NULL CHECK(revision>0),payload jsonb NOT NULL CHECK(octet_length(payload::text)<=131072),content_hash text NOT NULL,predecessor_id text REFERENCES decision_recap_versions(id),mode text NOT NULL CHECK(mode IN ('live','acceptance_test','replay','synthetic')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(user_id,pick_id,revision),UNIQUE(user_id,pick_id,content_hash),FOREIGN KEY(pick_id,user_id) REFERENCES picks(id,user_id));
CREATE INDEX pick_reason_owner_time ON pick_reason_versions(user_id,confirmed_at DESC);
CREATE INDEX pick_binding_watch ON pick_watch_bindings(user_id,watch_id,state);
CREATE INDEX pick_impact_owner_state ON pick_impact_assessments(user_id,state,checked_at DESC,id);
CREATE INDEX pick_action_owner ON pick_review_actions(user_id,assessment_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['pick_reason_versions','pick_watch_bindings','source_lineage_edges','pick_impact_assessments','pick_review_actions','decision_recap_versions'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY owner_isolation ON %I USING (user_id = current_setting(''app.user_id'',true)) WITH CHECK (user_id = current_setting(''app.user_id'',true))',t); END LOOP; END $$;
ALTER TABLE research_artifact_memory_grants DROP CONSTRAINT research_artifact_memory_grants_kind_check;
ALTER TABLE research_artifact_memory_grants ADD CONSTRAINT research_artifact_memory_grants_kind_check CHECK(kind IN ('source_change','forecast_rationale','forecast_result','drift_summary','decision_recap'));
ALTER TABLE pick_reason_versions ADD CONSTRAINT reason_assessment_identity UNIQUE(id,user_id,pick_id,pick_version,revision);
ALTER TABLE pick_impact_assessments ADD CONSTRAINT assessment_exact_reason FOREIGN KEY(reason_id,user_id,pick_id,pick_version,reason_revision) REFERENCES pick_reason_versions(id,user_id,pick_id,pick_version,revision);
ALTER TABLE decision_recap_versions ADD CONSTRAINT recap_owner_identity UNIQUE(id,user_id,pick_id);
ALTER TABLE decision_recap_versions ADD CONSTRAINT recap_predecessor_owner FOREIGN KEY(predecessor_id,user_id,pick_id) REFERENCES decision_recap_versions(id,user_id,pick_id);
CREATE FUNCTION protect_pick_monitoring_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Monitoring history is append-only'; END $$;
CREATE TRIGGER reason_append_only BEFORE UPDATE ON pick_reason_versions FOR EACH ROW EXECUTE FUNCTION protect_pick_monitoring_history();
CREATE TRIGGER impact_append_only BEFORE UPDATE ON pick_impact_assessments FOR EACH ROW EXECUTE FUNCTION protect_pick_monitoring_history();
CREATE TRIGGER action_append_only BEFORE UPDATE ON pick_review_actions FOR EACH ROW EXECUTE FUNCTION protect_pick_monitoring_history();
CREATE TRIGGER recap_append_only BEFORE UPDATE ON decision_recap_versions FOR EACH ROW EXECUTE FUNCTION protect_pick_monitoring_history();
ALTER TABLE source_watches ADD COLUMN structured_evidence jsonb;
ALTER TABLE source_change_events ADD COLUMN after_structured_evidence jsonb;
CREATE TABLE pick_review_proposals(user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,assessment_id text NOT NULL,request_id text NOT NULL,proposal_id text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(user_id,assessment_id),FOREIGN KEY(assessment_id,user_id) REFERENCES pick_impact_assessments(id,user_id),FOREIGN KEY(proposal_id) REFERENCES change_proposals(id));
ALTER TABLE pick_review_proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_isolation ON pick_review_proposals USING(user_id=current_setting('app.user_id',true)) WITH CHECK(user_id=current_setting('app.user_id',true));
ALTER TABLE source_change_events ADD COLUMN source_available boolean NOT NULL DEFAULT true;
CREATE UNIQUE INDEX source_lineage_exact_version ON source_lineage_edges(user_id,from_evidence_id,to_evidence_id,(payload->>'relation'),(payload->>'supportHash'),(payload->>'version'));
ALTER TABLE source_watches ADD COLUMN official_target jsonb;
